// G915 X key positions by Logitech control id, in the 2048 x 830 space of the drawing. Positions
// only (from the vendor app's layout data); the drawing itself is ours. `layout` marks keys that
// exist on one layout: the ANSI wide Enter and backslash, or the ISO tall Enter and the key left of it.
// `usage` is the key's HID usage (page 7), `g` its G-key number, `media` its consumer usage.
// Generated by scratchpad kb_gen_ts.py from the keyboard's control list.

export type KeyboardLayout = 'ansi' | 'iso';

export interface KeyShape {
  cid: number;
  x: number;
  y: number;
  w: number;
  h: number;
  usage?: number;
  g?: number;
  media?: number;
  round?: boolean;
  layout?: KeyboardLayout;
  /** Outline for a key that is not a rectangle (the ISO Enter). */
  path?: string;
}

export const ART = { width: 2048, height: 830 } as const;

